#!/usr/bin/env python3
"""Exact Farkas certificate for generic interior-ground support-seven H7b.

This verifier reconstructs the 184 generic H7b dihedral/global-sign order/sign orbits.
For each orbit it builds a necessary affine angle system using:

* the exact physical equilateral-pentagon turn-simplex facets;
* all seven full raw-ray orders at the convex-heptagon hull vertices;
* positive raw angular gaps and strict convex hull interior angles < pi;
* the interior-ground radial chirotope and positive ground radial gaps;
* the exact force-to-raw angle conversion on all present rays;
* all 56 Euclidean triangle angle-sum equations among the eight reciprocal points.

For 157 orbits the stored rational Farkas multipliers prove that the strict system is
empty.  The proof check below uses only integers and fractions; no numerical optimizer
or floating-point arithmetic is used.  The remaining 27 C7 orbits are only necessary
affine survivors and are not claimed realizable.
"""
from fractions import Fraction as Q
import itertools
from collections import Counter
N=range(1,8)
def edge(a,b):return tuple(sorted((a,b)))
def canon_cycle(seq):
    seq=tuple(seq);return min(o[k:]+o[:k] for o in (seq,tuple(reversed(seq))) for k in range(len(seq)))
def factors_all():
    fac=set()
    for p in itertools.permutations(N):
        c=canon_cycle(p)
        if p==c:fac.add(('C7',frozenset(edge(c[i],c[(i+1)%7]) for i in range(7))))
    for tri in itertools.combinations(N,3):
        tri=set(tri);q=tuple(v for v in N if v not in tri);te=frozenset(itertools.combinations(sorted(tri),2));qs=set()
        for p in itertools.permutations(q):
            c=canon_cycle(p)
            if p==c:qs.add(frozenset(edge(c[i],c[(i+1)%4]) for i in range(4)))
        for qe in qs:fac.add(('C3+C4',frozenset(set(te)|set(qe))))
    return fac
def cyc_order(i):return [((i-1+k)%7)+1 for k in range(1,7)]
def gchi(i,k,j):return 1 if cyc_order(i).index(j)<k else -1
slots=[ks for ks in itertools.product(range(1,6),repeat=7) if all(gchi(i,ks[i-1],j)==-gchi(j,ks[j-1],i) for i,j in itertools.combinations(N,2))]
assert len(slots)==57
def present_order(i,m,k):
    b=cyc_order(i);full=b[:k]+[0]+b[k:];return tuple(j for j in full if j==0 or edge(i,j) not in m)
def signings(m,ks):
    orders={i:present_order(i,m,ks[i-1]) for i in N};out=[]
    for bits in itertools.product((0,1),repeat=7):
        signs={};ok=True
        for i,b in zip(N,bits):
            for q,j in enumerate(orders[i]):
                s=1 if q in (1,3) else -1
                if not b:s=-s
                e=edge(i,j)
                if e in signs and signs[e]!=s:ok=False;break
                signs[e]=s
            if not ok:break
        if ok:out.append(tuple(sorted(signs.items())))
    return out
def maps():
    out=[]
    for shift in range(7):
        for refl in (0,1):
            mp={0:0}
            for i in N:
                z=i-1;zz=(shift-z)%7 if refl else (shift+z)%7;mp[i]=zz+1
            out.append(mp)
    return out
D=maps()
def transform(st,mp):
    typ,m,ks,signs=st;mset=frozenset(m);m2=tuple(sorted(edge(mp[a],mp[b]) for a,b in mset));orient=1 if ((mp[2]-mp[1])%7)==1 else -1;k2=[None]*7
    for oi in N:
        ni=mp[oi];vals={mp[j]:orient*gchi(oi,ks[oi-1],j) for j in N if j!=oi};o=cyc_order(ni);kk=sum(vals[j]>0 for j in o)
        assert all(vals[j]>0 for j in o[:kk]) and all(vals[j]<0 for j in o[kk:]);k2[ni-1]=kk
    s2=tuple(sorted((edge(mp[a],mp[b]),s) for (a,b),s in signs));return (typ,m2,tuple(k2),s2)
def complement(st):
    typ,m,ks,signs=st;return(typ,m,ks,tuple((e,-s) for e,s in signs))
states=[]
for typ,m in factors_all():
    for ks in slots:
        for signs in signings(m,ks):states.append((typ,tuple(sorted(m)),ks,signs))
S=set(states);seen=set();reps=[]
for st in sorted(S,key=repr):
    if st in seen:continue
    orb=set()
    for mp in D:
        t=transform(st,mp);orb.add(t);orb.add(complement(t))
    orb &= S;seen|=orb;reps.append(min(orb,key=repr))
assert len(reps)==184
assert Counter(st[0] for st in reps)==Counter({'C7':120,'C3+C4':64})

# Variables: x(i,k), i=1..7,k=0..4 (35); r(i,p), p=0..5 full raw hull-vertex
# gaps (42); h_i ground radial gaps (7).  Total 84. Angles are normalized by pi.
X={(i,k):5*(i-1)+k for i in N for k in range(5)}
R={(i,p):35+6*(i-1)+p for i in N for p in range(6)}
H={i:77+(i-1) for i in N};NV=84
def rowadd(a,j,c):
    c=Q(c)
    if c:
        a[j]=a.get(j,Q(0))+c
        if not a[j]:del a[j]
def addrows(a,b,scale=Q(1)):
    z=dict(a)
    for j,c in b.items():rowadd(z,j,scale*c)
    return z
def full_order(i,ks):
    b=cyc_order(i);k=ks[i-1];return tuple(b[:k]+[0]+b[k:])
def full_angle(i,a,b,ks):
    o=full_order(i,ks);pa=o.index(a);pb=o.index(b);lo,hi=sorted((pa,pb));r={}
    for p in range(lo,hi):rowadd(r,R[(i,p)],1)
    return r
def ground_ccw(a,b):
    r={};k=a
    while k!=b:
        rowadd(r,H[k],1);k=1 if k==7 else k+1
    return r
def ground_angle(a,b,ks):
    arc=ground_ccw(a,b);chi=gchi(a,ks[a-1],b)
    return (arc,Q(0)) if chi>0 else ({j:-c for j,c in arc.items()},Q(2))
def force_cycle(i,m,ks,sd):
    raw=present_order(i,m,ks[i-1]);pos=tuple(j for j in raw if sd[edge(i,j)]>0);neg=tuple(j for j in raw if sd[edge(i,j)]<0);cyc=pos+neg;assert len(cyc)==5;return cyc
def force_arc(cyc,i,a,b):
    r={};ia=cyc.index(a);ib=cyc.index(b);k=ia
    while k!=ib:
        rowadd(r,X[(i,k)],1);k=(k+1)%5
    return r
def raw_force_angle(cyc,i,a,b,sd,raw):
    arc=force_arc(cyc,i,a,b);same=sd[edge(i,a)]==sd[edge(i,b)];chi=1 if raw.index(b)>raw.index(a) else -1
    if same and chi>0:return arc,Q(0)
    if same and chi<0:return({j:-c for j,c in arc.items()},Q(2))
    if (not same) and chi>0:return arc,Q(-1)
    return({j:-c for j,c in arc.items()},Q(1))
def triangle_angle(v,a,b,ks):
    if v==0:return ground_angle(a,b,ks)
    return full_angle(v,a,b,ks),Q(0)
def build_system(st):
    typ,mt,ks,signst=st;m=frozenset(mt);sd=dict(signst);cyc={i:force_cycle(i,m,ks,sd) for i in N};raw={i:present_order(i,m,ks[i-1]) for i in N};eq=[];ine=[]
    # Equalities E(x)=d: seven pentagon angle sums, ground radial sum, 28 ties,
    # and all 56 triangle angle sums.
    for i in N:eq.append(({X[(i,k)]:Q(1) for k in range(5)},Q(2),('F',i)))
    eq.append(({H[i]:Q(1) for i in N},Q(2),('G',)))
    for i in N:
        po=present_order(i,m,ks[i-1])
        for a,b in zip(po,po[1:]):
            vr=full_angle(i,a,b,ks);vf,c=raw_force_angle(cyc,i,a,b,sd,po);eq.append((addrows(vr,vf,Q(-1)),c,('tie',i,a,b)))
    for a,b,c in itertools.combinations(range(8),3):
        rr={};cc=Q(0)
        for v,p,q in ((a,b,c),(b,a,c),(c,a,b)):
            vv,cv=triangle_angle(v,p,q,ks);rr=addrows(rr,vv);cc+=cv
        eq.append((rr,Q(1)-cc,('T',a,b,c)))
    assert len(eq)==92
    # Strict inequalities a(x)<b.
    for i in N:
        for k in range(5):
            rr={};rowadd(rr,X[(i,k)],-1);rowadd(rr,X[(i,(k+1)%5)],-1);rowadd(rr,X[(i,(k+3)%5)],1);ine.append((rr,Q(-1,3),('q',i,k)))
    for i in N:
        for p in range(6):ine.append(({R[(i,p)]:Q(-1)},Q(0),('r+',i,p)))
        ine.append(({R[(i,p)]:Q(1) for p in range(6)},Q(1),('interior<pi',i)))
    for i in N:ine.append(({H[i]:Q(-1)},Q(0),('h+',i)))
    for a,b in itertools.combinations(N,2):
        arc=ground_ccw(a,b);chi=gchi(a,ks[a-1],b)
        if chi>0:ine.append((arc,Q(1),('arc<pi',a,b)))
        else:ine.append(({j:-c for j,c in arc.items()},Q(-1),('arc>pi',a,b)))
    assert len(ine)==112
    return ine,eq

