EXCLUDED=set(CERTS)
SURVIVORS=[i for i in range(1,185) if i not in EXCLUDED]
assert SURVIVORS==[115,118,129,130,*range(134,149),*range(169,177)]
assert len(EXCLUDED)==157 and len(SURVIVORS)==27
assert Counter(reps[i-1][0] for i in SURVIVORS)==Counter({'C7':27})
assert Counter(reps[i-1][0] for i in EXCLUDED)==Counter({'C7':93,'C3+C4':64})
boundary=0;worst=None
for idx in sorted(EXCLUDED):
    ine,eq=build_system(reps[idx-1]);lam=[Q(0)]*len(ine);nu=[Q(0)]*len(eq)
    for j,n,d in CERTS[idx][0]:lam[j]=Q(n,d)
    for j,n,d in CERTS[idx][1]:nu[j]=Q(n,d)
    assert all(z>=0 for z in lam) and sum(lam,Q(0))==1
    coeff={};rhs=Q(0)
    for z,(r,b,_) in zip(lam,ine):
        if not z:continue
        for j,c in r.items():rowadd(coeff,j,z*c)
        rhs+=z*b
    for z,(r,d,_) in zip(nu,eq):
        if not z:continue
        for j,c in r.items():rowadd(coeff,j,-z*c)
        rhs-=z*d
    assert coeff=={},(idx,coeff)
    assert rhs<=0,(idx,rhs)
    boundary+=rhs==0
    if worst is None or rhs<worst:worst=rhs
print('PASS: exact full-angle H7b reduction')
print('generic H7b order/sign orbits: 184')
print('excluded by exact rational Farkas certificates:',len(EXCLUDED))
print('  C7 excluded: 93; C3+C4 excluded: 64 (all generic C3+C4)')
print('  boundary certificates:',boundary)
print('surviving necessary affine cases:',len(SURVIVORS),'all C7')
print('survivor ids:',SURVIVORS)
print('most negative certificate rhs:',worst)
